import{_ as t,o as e,c as l,a5 as r}from"./chunks/framework.CX7j2CRp.js";const _=JSON.parse('{"title":"杂项类博客写作指导","description":"","frontmatter":{},"headers":[],"relativePath":"public/prompt/博客/文章模板/杂项.md","filePath":"public/prompt/博客/文章模板/杂项.md","lastUpdated":1791612145000}'),i={name:"public/prompt/博客/文章模板/杂项.md"};function o(n,a,s,p,d,h){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="杂项类博客写作指导" tabindex="-1">杂项类博客写作指导 <a class="header-anchor" href="#杂项类博客写作指导" aria-label="Permalink to &quot;杂项类博客写作指导&quot;">​</a></h1><h2 id="文章定位" tabindex="-1">文章定位 <a class="header-anchor" href="#文章定位" aria-label="Permalink to &quot;文章定位&quot;">​</a></h2><p>用于整理不属于技术、金融、每日总结或专门领域模板的日常思考、经验记录、阅读感想和跨主题讨论。</p><p>以当前聊天已经讨论的内容为核心，不强行归类，不为了完整而补写未讨论过的故事、事实或结论。</p><h2 id="开头与展示" tabindex="-1">开头与展示 <a class="header-anchor" href="#开头与展示" aria-label="Permalink to &quot;开头与展示&quot;">​</a></h2><p>文章开头先放一段简短、纯文本的内容概述，说明本次记录的主题或缘由，避免以图片、HTML 图片标签或代码块开头，以免影响 VitePress 首页文章列表的展示。</p><p>图片、引用与列表只在能够帮助理解时使用，不追求固定配图数量。</p><h2 id="推荐组织方式" tabindex="-1">推荐组织方式 <a class="header-anchor" href="#推荐组织方式" aria-label="Permalink to &quot;推荐组织方式&quot;">​</a></h2><p>按照实际内容灵活选择：</p><ol><li><strong>缘起或背景</strong>：为什么开始思考或记录这个话题。</li><li><strong>主要观察与讨论</strong>：依次整理具体经历、发现、疑问和相关信息。</li><li><strong>自己的理解</strong>：明确哪些是事实、哪些是个人判断或尚未证实的猜测。</li><li><strong>结论与待续</strong>：保留当前阶段的收获，以及需要后续验证或继续讨论的事项。</li></ol><p>内容很短时，可以直接采用自然段，不必套用完整章节。</p><h2 id="写作原则" tabindex="-1">写作原则 <a class="header-anchor" href="#写作原则" aria-label="Permalink to &quot;写作原则&quot;">​</a></h2><ul><li>表达自然、克制、清晰，保留讨论本身的重点和个人思考过程。</li><li>不逐字复制聊天内容；去除重复、闲聊和无关枝节。</li><li>不编造时间、经历、数据、来源或他人的观点。</li><li>对不确定的事实作出标注；涉及实时信息时说明核实依据。</li><li>不泄露个人隐私、密钥或凭据。</li><li>当内容实际上适合专门领域模板时，优先使用对应模板，而不是杂项模板。</li></ul>',13)])])}const u=t(i,[["render",o]]);export{_ as __pageData,u as default};
